from decimal import Decimal, ROUND_HALF_UP
from openpyxl import load_workbook
path='/root/nasa_budget_recovered.xlsx'
wb=load_workbook(path,data_only=False)
missing=[]; errors=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            if cell.value == '???': missing.append(f'{ws.title}!{cell.coordinate}')
            if isinstance(cell.value,str) and cell.value.startswith('#'): errors.append(f'{ws.title}!{cell.coordinate}={cell.value}')
b=wb['Budget by Directorate']; yoy=wb['YoY Changes (%)']; shares=wb['Directorate Shares (%)']; growth=wb['Growth Analysis']
def rounded(value, places=2):
    return Decimal(str(value)).quantize(Decimal('1.'+'0'*places),rounding=ROUND_HALF_UP)
checks={
 '2016 total': b['K5'].value == sum(b.cell(5,col).value for col in range(2,11)),
 '2019 Space Operations link': b['F8'].value == growth['F5'].value,
 '2020 Science total': b['B9'].value == b['K9'].value-sum(b.cell(9,col).value for col in range(3,11)),
 '2021 Exploration YoY': yoy['E9'].value == float(rounded((Decimal(b['E10'].value)/Decimal(b['E9'].value)-1)*100)),
 '2021 total': b['K10'].value == sum(b.cell(10,col).value for col in range(2,11)),
 '2023 Aeronautics total': b['C12'].value == b['K12'].value-sum(b.cell(12,col).value for col in range(2,11) if col != 3),
 '2019 Space Technology YoY': yoy['D7'].value == float(rounded((Decimal(b['D8'].value)/Decimal(b['D7'].value)-1)*100)),
 '2021 Science YoY': yoy['B9'].value == float(rounded((Decimal(b['B10'].value)/Decimal(b['B9'].value)-1)*100)),
 '2021 Space Operations YoY': yoy['F9'].value == float(rounded((Decimal(b['F10'].value)/Decimal(b['F9'].value)-1)*100)),
 '2016 Space Operations share': shares['F5'].value == float(rounded(Decimal(b['F5'].value)/Decimal(b['K5'].value)*100)),
 '2021 Science share': shares['B10'].value == float(rounded(Decimal(b['B10'].value)/Decimal(b['K10'].value)*100)),
 'Exploration CAGR': growth['E4'].value == float(rounded(((Decimal(growth['E6'].value)/Decimal(growth['E5'].value))**(Decimal(1)/5)-1)*100)),
 'Science five-year change': growth['B7'].value == growth['B6'].value-growth['B5'].value,
 'Science annual average': growth['B8'].value == float(rounded(sum(Decimal(b.cell(row,2).value) for row in range(8,14))/6,1)),
}
print('placeholders:', missing)
print('errors:', errors)
for name, passed in checks.items(): print(f'{name}: {passed}')
if missing or errors or not all(checks.values()): raise SystemExit(1)
